                     size_t length);
        void (*write)(conf_object_t *img, const void *NOTNULL from_buf,
                      uint64 start, size_t length);
        int (*for_all_spages)(conf_object_t *img,
                              int (*NOTNULL f)(image_spage_t *NOTNULL p,
                                               uint64 ofs, void *arg),
